document.addEventListener('DOMContentLoaded', function () {
$('li.level-1').find('a[href ="/content/mca/global/en/additional-services/Enforcement.html"]').css("display","none");
    const nav = document.querySelector(".site-nav");
    const toggleBtn = document.querySelector(".menu-toggle");
    const menu = document.getElementById("primaryMenu");
    const overlay = document.querySelector(".menu-overlay");

    if (!nav || !toggleBtn || !menu) return;

    // Add has-submenu class for level-0 items (so ▼ appears)
    menu.querySelectorAll(":scope > li").forEach(li => {
        const hasDropdown = li.querySelector(":scope > ul.dropdown-level1");
        if (hasDropdown) li.classList.add("has-submenu");
    });


    const isMobile = () => window.matchMedia("(max-width: 992px)").matches;

    function openMenu() {
        nav.classList.add("is-open");
        toggleBtn.setAttribute("aria-expanded", "true");
        toggleBtn.setAttribute("aria-label", "Close menu");
        if (overlay) overlay.hidden = false;
    }

    function closeMenu() {
        nav.classList.remove("is-open");
        toggleBtn.setAttribute("aria-expanded", "false");
        toggleBtn.setAttribute("aria-label", "Open menu");
        if (overlay) overlay.hidden = true;

        // collapse all open submenus on close (mobile UX)
        menu.querySelectorAll("li.open").forEach(li => li.classList.remove("open"));
    }

    function toggleMenu() {
        nav.classList.contains("is-open") ? closeMenu() : openMenu();
    }

    toggleBtn.addEventListener("click", (e) => {
        e.preventDefault();
        toggleMenu();
    });

    overlay?.addEventListener("click", closeMenu);

    document.addEventListener("keydown", (e) => {
        if (e.key === "Escape" && nav.classList.contains("is-open")) {
            closeMenu();
        }
    });

    document.querySelectorAll("li").forEach(li => {
        const button = li.querySelector(":scope > .submenu-toggle");
        const submenu = li.querySelector(":scope > ul");

        // No submenu OR empty submenu → remove button
        if (!submenu || submenu.children.length === 0) {
            if (button) button.remove();
            return;
        }
    });


    // Mobile accordion: only one open at a time (per level)
    // Mobile: click ONLY on arrow button toggles submenu (link navigates normally)

    document.addEventListener(
        "click",
        function (e) {
            const btn = e.target.closest(".submenu-toggle");
            if (!btn) return;

            e.preventDefault();
            e.stopImmediatePropagation();

            const li = btn.closest("li");
            if (!li) return;

            const submenu = li.querySelector(":scope > ul");
            if (!submenu) return;

            const parentUl = li.parentElement;
            const isOpen = li.classList.contains("open");

            /* CLOSE SIBLINGS (same level) */
            if (parentUl) {
                parentUl.querySelectorAll(":scope > li.open").forEach(sibling => {
                    if (sibling !== li) {
                        sibling.classList.remove("open");
                        sibling.querySelectorAll("li.open")
                            .forEach(x => x.classList.remove("open"));
                        sibling.querySelectorAll(":scope > .submenu-toggle")
                            .forEach(b => b.setAttribute("aria-expanded", "false"));
                    }
                });
            }

            /* TOGGLE CURRENT */
            if (isOpen) {
                li.classList.remove("open");
                submenu.classList.remove("open");
                btn.setAttribute("aria-expanded", "false");
            } else {
                li.classList.add("open");
                submenu.classList.add("open");
                btn.setAttribute("aria-expanded", "true");
            }
        },
        true // capture mode (keep this)
    );


    window.addEventListener("resize", () => {
        if (!isMobile()) closeMenu();
    });
});


document.addEventListener('DOMContentLoaded', function () {
    const menu = document.getElementById('primaryMenu');
    if (!menu) return;


    /* =========================================================
     * Add class to ul.dropdown-level2 when a dropdown-level3 is opened
     * ========================================================= */
    (function addLevel2ClassWhenLevel3Visible() {
        const LEVEL2_OPEN_CLASS = 'has-level3-open';

        // Helper: the ul.dropdown-level2 for the current level-2 item
        function getParentLevel2Ul(node) {
            return node?.closest?.('ul.dropdown-level2');
        }

        // Helper: is this a level-2 li that actually has a level-3 submenu?
        function getLevel2LiWithLevel3(node) {
            const li = node?.closest?.('li.level-2');
            if (!li) return null;
            const level3 = li.querySelector(':scope > ul.dropdown-level3');
            return level3 ? li : null;
        }

        // Use delegated mouseover/mouseout so it works for all items
        menu.addEventListener('mouseover', (e) => {
            const li = getLevel2LiWithLevel3(e.target);
            if (!li) return;

            // Prevent re-trigger when moving within the same LI
            const from = e.relatedTarget;
            if (from && li.contains(from)) return;

            const parentUl = getParentLevel2Ul(li);
            parentUl?.classList.add(LEVEL2_OPEN_CLASS);
        });

        menu.addEventListener('mouseout', (e) => {
            const li = getLevel2LiWithLevel3(e.target);
            if (!li) return;

            // Prevent removal if moving into a child of that LI (like ul.dropdown-level3)
            const to = e.relatedTarget;
            if (to && li.contains(to)) return;

            const parentUl = getParentLevel2Ul(li);
            parentUl?.classList.remove(LEVEL2_OPEN_CLASS);
        });
    })();


    /* =========================================================
     * Add class to ul.dropdown-level3 when a dropdown-level4 is opened
     * ========================================================= */
    (function addLevel3ClassWhenLevel4Visible() {
        const LEVEL3_OPEN_CLASS = 'has-level4-open';

        // is this a level-3 li that actually has a level-4 submenu?
        function getLevel3LiWithLevel4(node) {
            const li = node?.closest?.('li.level-3');
            if (!li) return null;

            // level-4 submenu should be direct child of that level-3 li
            const level4 = li.querySelector(':scope > ul.dropdown-level4');
            return level4 ? li : null;
        }

        function getParentLevel3Ul(node) {
            return node?.closest?.('ul.dropdown-level3');
        }

        // Delegated hover detection
        menu.addEventListener('mouseover', (e) => {
            const li = getLevel3LiWithLevel4(e.target);
            if (!li) return;

            // ignore moves within the same LI
            const from = e.relatedTarget;
            if (from && li.contains(from)) return;

            const parentUl3 = getParentLevel3Ul(li);
            parentUl3?.classList.add(LEVEL3_OPEN_CLASS);
        });

        menu.addEventListener('mouseout', (e) => {
            const li = getLevel3LiWithLevel4(e.target);
            if (!li) return;

            // ignore if moving into a child of this LI (like ul.dropdown-level4)
            const to = e.relatedTarget;
            if (to && li.contains(to)) return;

            const parentUl3 = getParentLevel3Ul(li);
            parentUl3?.classList.remove(LEVEL3_OPEN_CLASS);
        });
    })();

    (function addClassToParentLiWhenLevel4Visible() {
        const PARENT_ACTIVE_CLASS = 'has-level4-visible';

        function updateForLevel3Li(level3Li) {
            if (!level3Li) return;

            const level4 = level3Li.querySelector(':scope > ul.dropdown-level4');
            if (!level4) {
                level3Li.classList.remove(PARENT_ACTIVE_CLASS);
                return;
            }

            // computed style check (works for :hover / :focus-within / JS toggles)
            const cs = window.getComputedStyle(level4);
            const isVisible = cs.display !== 'none' && cs.visibility !== 'hidden' && cs.opacity !== '0';

            level3Li.classList.toggle(PARENT_ACTIVE_CLASS, isVisible);
        }

        function updateFromEventTarget(target) {
            const level3Li = target?.closest?.('li.level-3');
            if (!level3Li) return;
            updateForLevel3Li(level3Li);
        }

        // Desktop hover + keyboard
        menu.addEventListener('pointerover', (e) => {
            updateFromEventTarget(e.target);
        });

        menu.addEventListener('pointerout', (e) => {
            // on leaving a level-3 item, re-check (it will become hidden)
            updateFromEventTarget(e.target);
        });

        menu.addEventListener('focusin', (e) => {
            updateFromEventTarget(e.target);
        });

        menu.addEventListener('focusout', (e) => {
            updateFromEventTarget(e.target);
        });

        // Initial pass (optional)
        menu.querySelectorAll('li.level-3').forEach(updateForLevel3Li);
    })();


    function markLevel0IfAllLevel2Empty() {
        menu.querySelectorAll(':scope > li.level-0.has-submenu').forEach(level0Li => {

            // Only level-2 ULs that belong to direct level-1 children of this level-0
            const level2Uls = level0Li.querySelectorAll(
                ':scope > ul.dropdown-level1 > li.level-1 > ul.dropdown-level2'
            );

            // If there are no level-2 ULs at all, don't mark (adjust if you want)
            if (level2Uls.length === 0) {
                level0Li.classList.remove('hasEmptyLevel2');
                return;
            }

            const allEmpty = Array.from(level2Uls).every(ul => ul.querySelectorAll(':scope > li').length === 0);

            level0Li.classList.toggle('hasEmptyLevel2', allEmpty);
        });
    }

    markLevel0IfAllLevel2Empty();
});



document.addEventListener('DOMContentLoaded', function () {
    const menu = document.getElementById('primaryMenu');
    if (!menu) return;

    /* =========================================================
     * NEW: Add class to level-1 LI if its level-2 UL is empty
     * ========================================================= */
    function markLevel1WithEmptyLevel2() {
        menu.querySelectorAll('ul.dropdown-level1 > li.level-1').forEach(level1Li => {
            // direct child level-2 ul under this level-1 li
            const level2Ul = level1Li.querySelector(':scope > ul.dropdown-level2');

            // treat missing level2 UL as "empty" OR only mark when it exists
            // If you want ONLY when ul exists, change condition to: if (level2Ul && ...)
            const isEmpty =
                !level2Ul || level2Ul.querySelectorAll(':scope > li').length === 0;

            if (isEmpty) {
                level1Li.classList.add('no-level2-items');
            } else {
                level1Li.classList.remove('no-level2-items');
            }
        });
    }

    // run once on load
    markLevel1WithEmptyLevel2();


    /* ---------------------------
     * 1) NEVER allow active inside nochild-level dropdowns
     * --------------------------- */
    function removeActiveFromNoChild() {
        menu.querySelectorAll('ul.dropdown-level1.nochild-level .active')
            .forEach(el => el.classList.remove('active'));
    }
    removeActiveFromNoChild();

    function inNoChildDropdown(node) {
        const dropdown = node?.closest?.('ul.dropdown-level1');
        return !!(dropdown && dropdown.classList.contains('nochild-level'));
    }

    /* ---------------------------
     * 2) Identify Services level-0 and Master Data default (level-1)
     * --------------------------- */
    const servicesLevel0 = Array.from(menu.querySelectorAll(':scope > li.level-0'))
        .find(li => (li.querySelector(':scope > a')?.textContent || '').trim().toLowerCase() === 'services');

    let masterDataLi = null;
    let servicesDropdown = null;

    if (servicesLevel0) {
        servicesDropdown = servicesLevel0.querySelector(':scope > ul.dropdown-level1');
        if (servicesDropdown) {
            masterDataLi = Array.from(servicesDropdown.querySelectorAll(':scope > li.level-1'))
                .find(li => (li.querySelector(':scope > a')?.textContent || '').trim().toLowerCase() === 'master data');
        }
    }

    function clearLevel2Active(scopeEl) {
        (scopeEl || menu).querySelectorAll('li.level-2.active')
            .forEach(li => li.classList.remove('active'));
    }

    function setDefaultMasterActive() {
        if (!masterDataLi) return;
        const dropdown = masterDataLi.closest('ul.dropdown-level1');
        if (!dropdown) return;

        dropdown.querySelectorAll(':scope > li.level-1.active')
            .forEach(li => li.classList.remove('active'));

        clearLevel2Active(dropdown);

        masterDataLi.classList.add('active');
    }

    setDefaultMasterActive();

    /* ---------------------------
     * 3) Active setters
     * --------------------------- */
    function setActiveLevel1(level1Li) {
        if (!level1Li) return;
        if (inNoChildDropdown(level1Li)) return;

        const dropdown = level1Li.closest('ul.dropdown-level1');
        if (!dropdown) return;

        dropdown.querySelectorAll(':scope > li.level-1.active')
            .forEach(li => { if (li !== level1Li) li.classList.remove('active'); });

        level1Li.classList.add('active');
    }

    function setActiveLevel2(level2Li) {
        if (!level2Li) return;
        if (inNoChildDropdown(level2Li)) return;

        const level2List = level2Li.closest('ul.dropdown-level2');
        if (!level2List) return;

        level2List.querySelectorAll(':scope > li.level-2.active')
            .forEach(li => { if (li !== level2Li) li.classList.remove('active'); });

        level2Li.classList.add('active');
    }

    /* ---------------------------
     * 4) Hover behavior
     * --------------------------- */
    menu.addEventListener('mouseover', function (e) {
        const t = e.target;

        const level3 = t.closest('li.level-3');
        const dropdown3 = t.closest('ul.dropdown-level3');
        if ((level3 || dropdown3) && menu.contains(t)) {
            const parentLevel2 = t.closest('li.level-2');
            const parentLevel1 = t.closest('li.level-1');

            setActiveLevel1(parentLevel1);
            setActiveLevel2(parentLevel2);
            return;
        }

        const level2 = t.closest('li.level-2');
        if (level2 && menu.contains(level2)) {
            const parentLevel1 = level2.closest('li.level-1');
            setActiveLevel1(parentLevel1);
            setActiveLevel2(level2);
            return;
        }

        const level1 = t.closest('li.level-1');
        if (level1 && menu.contains(level1)) {
            if (inNoChildDropdown(level1)) return;

            setActiveLevel1(level1);

            const dropdown = level1.closest('ul.dropdown-level1');
            clearLevel2Active(dropdown);
            return;
        }
    });

    /* ---------------------------
     * 5) Restore Master Data when leaving Services dropdown
     * --------------------------- */
    if (servicesDropdown) {
        servicesDropdown.addEventListener('mouseleave', function () {
            setDefaultMasterActive();
            removeActiveFromNoChild();
        });
    }

    /* ---------------------------
     * 6) Safety: leaving whole menu restores defaults
     * --------------------------- */
    menu.addEventListener('mouseleave', function () {
        setDefaultMasterActive();
        removeActiveFromNoChild();
    });
    (function addClassToLevel3WhenLevel4IsHovered() {
        const LEVEL3_HOVER_CLASS = 'level3-level4-hover';

        // Returns the li.level-3 that owns a dropdown-level4 (or null)
        function getLevel3LiWithLevel4(node) {
            const li = node?.closest?.('li.level-3');
            if (!li) return null;

            // Ensure this level-3 actually has a level-4 submenu
            const level4 = li.querySelector(':scope > ul.dropdown-level4');
            return level4 ? li : null;
        }

        // Use pointer events (works for mouse + pen; fine for desktop hover)
        menu.addEventListener('pointerover', (e) => {
            const li = getLevel3LiWithLevel4(e.target);
            if (!li) return;

            // Ignore internal moves within the same LI
            const from = e.relatedTarget;
            if (from && li.contains(from)) return;

            li.classList.add(LEVEL3_HOVER_CLASS);
        });

        menu.addEventListener('pointerout', (e) => {
            const li = getLevel3LiWithLevel4(e.target);
            if (!li) return;

            // Ignore when moving into children (like ul.dropdown-level4)
            const to = e.relatedTarget;
            if (to && li.contains(to)) return;

            li.classList.remove(LEVEL3_HOVER_CLASS);
        });

        // Optional: keyboard accessibility (tabbing into level-4 keeps class)
        menu.addEventListener('focusin', (e) => {
            const li = getLevel3LiWithLevel4(e.target);
            if (!li) return;
            li.classList.add(LEVEL3_HOVER_CLASS);
        });

        menu.addEventListener('focusout', (e) => {
            const li = getLevel3LiWithLevel4(e.target);
            if (!li) return;

            const to = e.relatedTarget;
            if (to && li.contains(to)) return;

            li.classList.remove(LEVEL3_HOVER_CLASS);
        });
    })();

});